-- >>> 010_ledger_immutability.sql

-- ---------------------------------------------------------------------------
-- Ledger immutability
--
-- The ledger is the bank. Corrections happen by posting a reversing journal,
-- never by editing or deleting a row, so the database refuses both outright.
-- Application code that tries it gets a Postgres error, not a silent success.
-- ---------------------------------------------------------------------------

CREATE SCHEMA IF NOT EXISTS meridian;

CREATE OR REPLACE FUNCTION meridian.reject_ledger_mutation() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'LEDGER_IMMUTABLE: % is not permitted on %', TG_OP, TG_TABLE_NAME
    USING ERRCODE = 'restrict_violation',
          HINT = 'Post a reversing journal transaction instead of rewriting history.';
END;
$$;

-- One leg of a journal is a fact. INSERT only, forever.
DROP TRIGGER IF EXISTS ledger_entries_append_only ON ledger_entries;
CREATE TRIGGER ledger_entries_append_only
  BEFORE UPDATE OR DELETE ON ledger_entries
  FOR EACH ROW EXECUTE FUNCTION meridian.reject_ledger_mutation();

-- A journal header may only gain a reversal pointer. Everything else is frozen.
CREATE OR REPLACE FUNCTION meridian.guard_journal_update() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  mutable text[] := ARRAY['status', 'reversed_by_id', 'reversed_at'];
BEGIN
  IF (to_jsonb(NEW) - mutable) IS DISTINCT FROM (to_jsonb(OLD) - mutable) THEN
    RAISE EXCEPTION
      'LEDGER_IMMUTABLE: journal_transactions are append-only; only % may change',
      array_to_string(mutable, ', ')
      USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS journal_transactions_immutable ON journal_transactions;
CREATE TRIGGER journal_transactions_immutable
  BEFORE UPDATE ON journal_transactions
  FOR EACH ROW EXECUTE FUNCTION meridian.guard_journal_update();

DROP TRIGGER IF EXISTS journal_transactions_append_only ON journal_transactions;
CREATE TRIGGER journal_transactions_append_only
  BEFORE DELETE ON journal_transactions
  FOR EACH ROW EXECUTE FUNCTION meridian.reject_ledger_mutation();

-- The audit log is hash-chained too: rewriting an entry breaks the chain proof.
DROP TRIGGER IF EXISTS audit_logs_append_only ON audit_logs;
CREATE TRIGGER audit_logs_append_only
  BEFORE UPDATE OR DELETE ON audit_logs
  FOR EACH ROW EXECUTE FUNCTION meridian.reject_ledger_mutation();

-- >>> 020_journal_balance_guard.sql

-- ---------------------------------------------------------------------------
-- Double-entry enforcement
--
-- A journal transaction is balanced if and only if the sum of its debits equals
-- the sum of its credits. Application code checks this too, but the check that
-- matters is this one: a deferrable constraint trigger evaluated at COMMIT, so a
-- half-written journal can never become visible to any other transaction, no
-- matter which code path wrote it or who connects to the database later.
--
-- The same trigger asserts the header agrees with its legs: amount_minor equals
-- the debit total, entry_count equals the number of legs, every leg is in the
-- journal's currency, and there are at least two legs.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION meridian.assert_journal_balanced() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  header      journal_transactions%ROWTYPE;
  leg_count   int;
  debit_total bigint;
  credit_total bigint;
  off_currency int;
BEGIN
  SELECT * INTO header FROM journal_transactions WHERE id = NEW.journal_transaction_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'JOURNAL_UNBALANCED: ledger entry references missing journal %',
      NEW.journal_transaction_id USING ERRCODE = 'check_violation';
  END IF;

  SELECT count(*),
         COALESCE(sum(amount_minor) FILTER (WHERE direction = 'DEBIT'), 0),
         COALESCE(sum(amount_minor) FILTER (WHERE direction = 'CREDIT'), 0),
         count(*) FILTER (WHERE currency <> header.currency)
    INTO leg_count, debit_total, credit_total, off_currency
    FROM ledger_entries
   WHERE journal_transaction_id = NEW.journal_transaction_id;

  IF off_currency > 0 THEN
    RAISE EXCEPTION
      'JOURNAL_UNBALANCED: journal % mixes currencies; its legs must all be %',
      header.reference, header.currency USING ERRCODE = 'check_violation';
  END IF;

  IF leg_count < 2 THEN
    RAISE EXCEPTION 'JOURNAL_UNBALANCED: journal % has % leg(s); double entry needs at least 2',
      header.reference, leg_count USING ERRCODE = 'check_violation';
  END IF;

  IF debit_total <> credit_total THEN
    RAISE EXCEPTION
      'JOURNAL_UNBALANCED: journal % is out by % minor units (debits %, credits %)',
      header.reference, debit_total - credit_total, debit_total, credit_total
      USING ERRCODE = 'check_violation';
  END IF;

  IF debit_total <> header.amount_minor THEN
    RAISE EXCEPTION
      'JOURNAL_UNBALANCED: journal % header says % but its legs total %',
      header.reference, header.amount_minor, debit_total USING ERRCODE = 'check_violation';
  END IF;

  IF leg_count <> header.entry_count THEN
    RAISE EXCEPTION
      'JOURNAL_UNBALANCED: journal % header says % legs but % were written',
      header.reference, header.entry_count, leg_count USING ERRCODE = 'check_violation';
  END IF;

  RETURN NULL;
END;
$$;

DROP TRIGGER IF EXISTS ledger_entries_balanced ON ledger_entries;
CREATE CONSTRAINT TRIGGER ledger_entries_balanced
  AFTER INSERT ON ledger_entries
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION meridian.assert_journal_balanced();

-- Posting is a per-account affair: this index keeps the balance trigger's lookup
-- of a journal's legs cheap even for a journal with many legs.
DROP INDEX IF EXISTS ledger_entries_journal_idx;
CREATE INDEX ledger_entries_journal_idx ON ledger_entries (journal_transaction_id, direction);

-- >>> 030_money_constraints.sql

-- ---------------------------------------------------------------------------
-- Money-shaped constraints
--
-- Amounts are integers of minor units (kobo). These checks make a negative
-- magnitude, a mismatched currency string or a cache that contradicts its own
-- arithmetic unrepresentable.
-- ---------------------------------------------------------------------------

ALTER TABLE ledger_entries
  DROP CONSTRAINT IF EXISTS ledger_entries_magnitude_positive,
  ADD CONSTRAINT ledger_entries_magnitude_positive CHECK (amount_minor > 0),
  DROP CONSTRAINT IF EXISTS ledger_entries_currency_format,
  ADD CONSTRAINT ledger_entries_currency_format CHECK (currency ~ '^[A-Z]{3}$');

ALTER TABLE journal_transactions
  DROP CONSTRAINT IF EXISTS journal_amount_positive,
  ADD CONSTRAINT journal_amount_positive CHECK (amount_minor > 0),
  DROP CONSTRAINT IF EXISTS journal_entry_count_min,
  ADD CONSTRAINT journal_entry_count_min CHECK (entry_count >= 2),
  DROP CONSTRAINT IF EXISTS journal_currency_format,
  ADD CONSTRAINT journal_currency_format CHECK (currency ~ '^[A-Z]{3}$');

ALTER TABLE accounts
  DROP CONSTRAINT IF EXISTS accounts_currency_format,
  ADD CONSTRAINT accounts_currency_format CHECK (currency ~ '^[A-Z]{3}$'),
  DROP CONSTRAINT IF EXISTS accounts_overdraft_non_negative,
  ADD CONSTRAINT accounts_overdraft_non_negative CHECK (overdraft_limit_minor >= 0 AND minimum_balance_minor >= 0);

-- available = balance - holds is an identity of the cache, not an opinion.
ALTER TABLE account_balances
  DROP CONSTRAINT IF EXISTS account_balances_available_identity,
  ADD CONSTRAINT account_balances_available_identity CHECK (available_minor = balance_minor - holds_minor),
  DROP CONSTRAINT IF EXISTS account_balances_holds_non_negative,
  ADD CONSTRAINT account_balances_holds_non_negative CHECK (holds_minor >= 0);

ALTER TABLE transfers
  DROP CONSTRAINT IF EXISTS transfers_amount_positive,
  ADD CONSTRAINT transfers_amount_positive CHECK (amount_minor > 0 AND fee_minor >= 0),
  DROP CONSTRAINT IF EXISTS transfers_reversed_within_amount,
  ADD CONSTRAINT transfers_reversed_within_amount CHECK (reversed_minor >= 0 AND reversed_minor <= amount_minor),
  DROP CONSTRAINT IF EXISTS transfers_currency_format,
  ADD CONSTRAINT transfers_currency_format CHECK (currency ~ '^[A-Z]{3}$');

ALTER TABLE holds
  DROP CONSTRAINT IF EXISTS holds_amounts,
  ADD CONSTRAINT holds_amounts CHECK (amount_minor > 0 AND captured_minor >= 0 AND captured_minor <= amount_minor);

ALTER TABLE limit_usages
  DROP CONSTRAINT IF EXISTS limit_usages_non_negative,
  ADD CONSTRAINT limit_usages_non_negative CHECK (used_minor >= 0 AND transfer_count >= 0);

ALTER TABLE interest_accruals
  DROP CONSTRAINT IF EXISTS interest_accruals_non_negative,
  ADD CONSTRAINT interest_accruals_non_negative CHECK (accrued_minor >= 0 AND average_balance_minor >= 0);

ALTER TABLE loan_schedules
  DROP CONSTRAINT IF EXISTS loan_schedules_components,
  ADD CONSTRAINT loan_schedules_components
    CHECK (payment_minor = interest_minor + principal_minor AND paid_minor >= 0);

-- Nigeria: a NUBAN is exactly ten digits, a BVN exactly eleven.
ALTER TABLE accounts
  DROP CONSTRAINT IF EXISTS accounts_nuban_format,
  ADD CONSTRAINT accounts_nuban_format CHECK (account_number ~ '^\d{10}$');

-- Identity data is normalised on write, so lookups and de-duplication are exact.
ALTER TABLE users
  DROP CONSTRAINT IF EXISTS users_email_lowercase,
  ADD CONSTRAINT users_email_lowercase CHECK (email = lower(email)),
  DROP CONSTRAINT IF EXISTS users_phone_format,
  ADD CONSTRAINT users_phone_format CHECK (phone ~ '^(\+234|0)[789][01]\d{8}$'),
  DROP CONSTRAINT IF EXISTS users_bvn_last4_format,
  ADD CONSTRAINT users_bvn_last4_format CHECK (bvn_last4 ~ '^\d{4}$'),
  -- KYC floor: a Nigerian bank account holder is at least 18.
  DROP CONSTRAINT IF EXISTS users_minimum_age,
  ADD CONSTRAINT users_minimum_age CHECK (date_of_birth <= (CURRENT_DATE - INTERVAL '18 years')),
  DROP CONSTRAINT IF EXISTS users_failed_login_non_negative,
  ADD CONSTRAINT users_failed_login_non_negative CHECK (failed_login_count >= 0);

-- >>> 040_transfer_state_guard.sql

-- ---------------------------------------------------------------------------
-- Transfer state machine, enforced by the database
--
-- The API has a state machine in TypeScript that produces good error messages and
-- emits events. This trigger is the backstop: even a migration script, a psql
-- session or a future refactor cannot move a transfer through an illegal
-- transition. The transition table below is the single source of truth for what
-- "legal" means.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION meridian.guard_transfer_status() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  permitted boolean;
BEGIN
  IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;

  SELECT EXISTS (
    SELECT 1
      FROM (VALUES
        -- New payment intents either go straight through or stop for review.
        ('PENDING', 'RISK_REVIEW'),
        ('PENDING', 'PROCESSING'),
        ('PENDING', 'BLOCKED'),
        ('PENDING', 'FAILED'),
        -- An officer clears a review (or blocks it).
        ('RISK_REVIEW', 'PROCESSING'),
        ('RISK_REVIEW', 'BLOCKED'),
        ('RISK_REVIEW', 'FAILED'),
        -- A blocked transfer can be released by an authorised officer.
        ('BLOCKED', 'PROCESSING'),
        -- In flight: settles or fails. Never jumps straight to REVERSED.
        ('PROCESSING', 'SETTLED'),
        ('PROCESSING', 'FAILED'),
        -- Money that moved can be undone, wholly or in part.
        ('SETTLED', 'REVERSED'),
        ('SETTLED', 'REFUNDED'),
        ('REVERSED', 'REFUNDED')
      ) AS allowed (from_status, to_status)
     WHERE allowed.from_status = OLD.status::text
       AND allowed.to_status = NEW.status::text
  ) INTO permitted;

  IF NOT permitted THEN
    RAISE EXCEPTION 'TRANSFER_INVALID_STATE: % -> % is not an allowed transition',
      OLD.status, NEW.status
      USING ERRCODE = 'check_violation',
            HINT = 'Route the change through TransferStateMachineService.';
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS transfers_status_machine ON transfers;
CREATE TRIGGER transfers_status_machine
  BEFORE UPDATE OF status ON transfers
  FOR EACH ROW EXECUTE FUNCTION meridian.guard_transfer_status();

-- >>> 050_balance_autocreate.sql

-- ---------------------------------------------------------------------------
-- Every account always has a balance row
--
-- Posting code locks and updates `account_balances` before writing a leg, so the
-- row must exist from the moment the account does. Creating it in the application
-- would leave a window where an account exists with no cache; creating it here
-- makes that state unrepresentable.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION meridian.create_account_balance() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO account_balances (account_id, balance_minor, available_minor, holds_minor, entry_count, version)
  VALUES (NEW.id, 0, 0, 0, 0, 0)
  ON CONFLICT (account_id) DO NOTHING;
  RETURN NULL;
END;
$$;

DROP TRIGGER IF EXISTS accounts_create_balance ON accounts;
CREATE TRIGGER accounts_create_balance
  AFTER INSERT ON accounts
  FOR EACH ROW EXECUTE FUNCTION meridian.create_account_balance();

-- >>> 060_indexes.sql

-- ---------------------------------------------------------------------------
-- Partial indexes for the queries the hot paths actually run
--
-- Prisma generates indexes for every `@@index`, but it cannot express partial
-- indexes. These cover the shapes that dominate at runtime: "this account's
-- recent statement", "which holds are still active", "what has the outbox not yet
-- published", and "which transfers are still in flight".
-- ---------------------------------------------------------------------------

-- Statement page: newest legs for one account.
CREATE INDEX IF NOT EXISTS ledger_entries_account_recent_idx
  ON ledger_entries (account_id, sequence DESC);

-- Releasing and expiring holds only ever looks at ACTIVE rows.
CREATE INDEX IF NOT EXISTS holds_active_idx
  ON holds (account_id, expires_at)
  WHERE status = 'ACTIVE';

-- The outbox relay polls exactly this, thousands of times an hour.
CREATE INDEX IF NOT EXISTS outbox_pending_idx
  ON outbox_events (available_at)
  WHERE processed_at IS NULL AND status = 'PENDING';

-- The settlement worker sweeps in-flight transfers.
CREATE INDEX IF NOT EXISTS transfers_in_flight_idx
  ON transfers (created_at)
  WHERE status IN ('PENDING', 'PROCESSING', 'RISK_REVIEW');

-- Risk engine: rolling window over a user's recent activity.
CREATE INDEX IF NOT EXISTS transfers_user_recent_idx
  ON transfers (initiated_by_user_id, created_at DESC);

CREATE INDEX IF NOT EXISTS risk_events_transfer_idx
  ON risk_events (transfer_id)
  WHERE transfer_id IS NOT NULL;

-- Reconciliation compares a journal's legs to its header, per currency.
CREATE INDEX IF NOT EXISTS ledger_entries_currency_idx
  ON ledger_entries (currency, journal_transaction_id);

-- FX rate lookup: latest effective rate for a pair.
CREATE INDEX IF NOT EXISTS fx_rates_pair_effective_idx
  ON fx_rates (base, quote, effective_at DESC);

-- Uncapitalised interest still owed to customers.
CREATE INDEX IF NOT EXISTS interest_accruals_open_idx
  ON interest_accruals (accrual_date)
  WHERE capitalised = false;

-- Loan collections: installments that are due and unpaid.
CREATE INDEX IF NOT EXISTS loan_schedules_due_idx
  ON loan_schedules (due_date, loan_id)
  WHERE status <> 'PAID';

-- Scheduled transfers that are due to run.
CREATE INDEX IF NOT EXISTS scheduled_transfers_due_idx
  ON scheduled_transfers (next_run_at)
  WHERE status = 'ACTIVE';

-- >>> 070_proof_functions.sql

-- ---------------------------------------------------------------------------
-- Ledger proofs
--
-- These functions are the bank's own audit tools. They answer, in the database and
-- in one round trip, the questions a bank must be able to answer on demand:
--
--   * does the whole ledger sum to zero, per currency?      ledger_imbalance()
--   * what does the ledger say this account's balance is?   account_ledger_balance()
--   * has any journal row been tampered with?               verify_ledger_chain()
--   * does the cached balance still match the ledger?       reconciliation_report()
--
-- `GET /ops/ledger/verify` and the nightly reconciliation job both call these, and
-- the integration tests assert they stay at zero on a busy ledger.
-- ---------------------------------------------------------------------------

-- Debits minus credits for one currency, or for the whole book when omitted.
-- Zero is the only acceptable answer.
CREATE OR REPLACE FUNCTION meridian.ledger_imbalance(p_currency char(3) DEFAULT NULL)
RETURNS bigint
LANGUAGE sql STABLE AS $$
  SELECT COALESCE(SUM(CASE WHEN direction = 'DEBIT' THEN amount_minor ELSE -amount_minor END), 0)::bigint
    FROM ledger_entries
   WHERE p_currency IS NULL OR currency = p_currency;
$$;

-- The ledger's answer for one account, signed in the account's normal-balance
-- direction, which is exactly what `account_balances.balance_minor` caches.
CREATE OR REPLACE FUNCTION meridian.account_ledger_balance(p_account_id uuid)
RETURNS bigint
LANGUAGE sql STABLE AS $$
  SELECT COALESCE(
           SUM(CASE WHEN e.direction::text = a.normal_balance::text THEN e.amount_minor ELSE -e.amount_minor END),
           0
         )::bigint
    FROM accounts a
    JOIN ledger_entries e ON e.account_id = a.id
   WHERE a.id = p_account_id;
$$;

-- Per-currency trial balance: the aggregate proof that nothing leaked.
CREATE OR REPLACE FUNCTION meridian.trial_balance()
RETURNS TABLE (currency char(3), debit_total bigint, credit_total bigint, imbalance bigint, legs bigint)
LANGUAGE sql STABLE AS $$
  SELECT currency,
         COALESCE(SUM(amount_minor) FILTER (WHERE direction = 'DEBIT'), 0)::bigint,
         COALESCE(SUM(amount_minor) FILTER (WHERE direction = 'CREDIT'), 0)::bigint,
         COALESCE(SUM(CASE WHEN direction = 'DEBIT' THEN amount_minor ELSE -amount_minor END), 0)::bigint,
         count(*)::bigint
    FROM ledger_entries
   GROUP BY currency
   ORDER BY currency;
$$;

-- Walk the hash chain in sequence order and report every link that does not
-- connect. An empty result is the proof that no journal row was altered after the
-- fact.
CREATE OR REPLACE FUNCTION meridian.verify_ledger_chain()
RETURNS TABLE (sequence bigint, reference text, issue text)
LANGUAGE sql STABLE AS $$
  WITH ordered AS (
    SELECT j.sequence,
           j.reference,
           j.hash_prev,
           lag(j.hash) OVER (ORDER BY j.sequence) AS expected_prev,
           row_number() OVER (ORDER BY j.sequence) AS position
      FROM journal_transactions j
  )
  SELECT sequence,
         reference,
         CASE
           WHEN position = 1 AND hash_prev IS NOT NULL THEN 'first journal must not have a predecessor hash'
           ELSE 'hash_prev does not match the previous journal hash'
         END
    FROM ordered
   WHERE (position = 1 AND hash_prev IS NOT NULL)
      OR (position > 1 AND hash_prev IS DISTINCT FROM expected_prev)
   ORDER BY sequence;
$$;

-- Compare every materialised balance with the ledger it supposedly caches. Rows are
-- returned only when they disagree, so "no rows" means "the book is proven".
CREATE OR REPLACE FUNCTION meridian.reconciliation_report()
RETURNS TABLE (account_id uuid, currency char(3), cached_minor bigint, ledger_minor bigint, drift_minor bigint, leg_count bigint)
LANGUAGE sql STABLE AS $$
  SELECT a.id,
         a.currency,
         COALESCE(b.balance_minor, 0)::bigint,
         meridian.account_ledger_balance(a.id),
         (COALESCE(b.balance_minor, 0) - meridian.account_ledger_balance(a.id))::bigint,
         COALESCE(b.entry_count, 0)::bigint
    FROM accounts a
    LEFT JOIN account_balances b ON b.account_id = a.id
   WHERE COALESCE(b.balance_minor, 0) <> meridian.account_ledger_balance(a.id)
   ORDER BY a.currency, a.account_number;
$$;
